startGuideActionMenu: "Odaberite izbornik",
startGuideActivity: "Aktivnosti su zadaci koji su planirani u projektima.<br/> Možete stvoriti WBS (strukturu raspodijela svih posla u projektu). <br/> Nema ograničenja razina / faza / pod-faza / zadatke / podzadatke.",
startGuideAffectation: "Resurs mora se dodijeliti projektu da vidi relevantne elemente. <br/> Dodjela projektu automatski dozvoli resursu pristup potprojektima.",
startGuideClient: "Kupci su entitete za koje radite. <br/> Mogu biti unutara ili van vaše organizacije.",
startGuideContact: "Kontakti su osobe s kojima ste u kontaktu unutar entiteta klijenata.",
startGuideFooter: "To su glavne funkcije sistema. <br/> Nakon što ste upoznati s tim&#44; također istražite druge module za vaše upravljanje projektima.",
startGuideImputation: "Resursi utipkavaju stvarni posao u 'stvarni rad  izvješće' dnevno po aktivnostima. <br/> Ponovno ocjenivanje&#44; preostale radove ažuriraju se sa stvarnim napretkom projekta.",
startGuideIntro: "Evo kratak uvod&#44; koji vam olakša prve korake s ProjeQtOr.<br> Slijedite ovim korakima kako bi postavili prve elemente. <br> Jednostavno pritisnute tipku F1 za upute za uporabu i dodatnu pomoć.<br>  Vratite se na 'Danas-stranicu' kako bi dobili pomoć.",
startGuideMilestone: "Prekretnice su vrlo bitan datum projekta. <br/> Definiraju projektu dolazno (fiksna prektretnica) ili dostavu (fleksibilna prekretnica).",
startGuidePlanning: "Planiranje pokazuje Gantt dijagram. <br/> Za raspored aktivnosti&#44; resursa s planom rada dodjelite na aktivnost &#44; jer 'planiranje' očekuje rada pogon.<br/> Zatim možete odrediti zavisnosti između zadataka (prethodnik elemenata) i događaje. <br/> Sada možete pokrenuti izračun plan koji uzima u obzir sve ograničenja resursa.",
startGuideProject: "Projekt je glavni element u ProjeQtOr. <br/> Svaki element spojen projektu.<br/> Prava pristupa su navedeni na razini projekta.",
startGuideResource: "Resursi su osobe koje rade na poslovima. <br/> Ako markirate &#34;je korisnik&#34;&#44; onda je resurs omogćen se osobno prijaviti u ProjeQtOr.",
startGuideTicket: "Tiketi se mogu koristiti za svaki događaj kao pogreške&#44; zahtjeve itd. i dodjeljuju se projektu. <br/> Oni mogu jednostavno biti kopirani na  aktivitet kada je to potrebno&#44; bez da podaci moraju biti ponovno uptipkani. Veza podrijetlo elementa i tiket su vidljivi.",
